script:
if doc.parent_task:
    task = frappe.get_doc('Task', doc.parent_task)
    if not task.is_group:
        task.is_group = True  # Устанавливаем чекбокс is_group
        task.save()  # Сохраняем изменения

if (doc.status == 'Resolved' or doc.status == 'Closed') and doc.project:
    project_id = doc.project 

    # Получаем значение поля is_active для данного проекта
    project_status = frappe.db.get_value('Project', project_id, 'is_active')

    if project_status == 'No':
        frappe.throw("Только задачи согласованного проекта могут быть переведены в финальный статус")

if doc.status == 'Completed' and doc.project:
    project_id = doc.project 

    # Получаем значение поля is_active для данного проекта
    project_status = frappe.db.get_value('Project', project_id, 'is_active')

    if project_status == 'No':
        frappe.throw("Только задачи согласованного проекта могут быть переведены в финальный статус")

if not doc.custom_planned_start_date:
    doc.custom_planned_start_date = doc.exp_start_date

if not doc.custom_planned_end_date:
    doc.custom_planned_end_date = doc.exp_end_date

workflow_tasks = frappe.get_all('Workflow Task', filters={
   'wt_docname': doc.name
}, ignore_permissions=True)

for task in workflow_tasks:
   task_doc = frappe.get_doc('Workflow Task', task.name)
   task_doc.delete(ignore_permissions=True)

#ISS-2024-02939
def ceil(a, b):
    c = a // b
    if a % b != 0 or a == 0:
        c = c + 1
    return c
#Если дочерняя задача:
if doc.parent_task:
    #Если проект задачи не указан, то = проекту родительской задачи 
    if not doc.project:
        doc.project = frappe.db.get_value('Task',doc.parent_task,'project')
    #Если прогнозные даты не указаны, то = прогнозным датам родительской задачи.
    if not doc.exp_start_date:
        doc.exp_start_date = frappe.db.get_value('Task',doc.parent_task,'exp_start_date')
    if not doc.exp_end_date:
        doc.exp_end_date = frappe.db.get_value('Task',doc.parent_task,'exp_end_date')
        
today = frappe.utils.today()
expected_time = doc.expected_time if doc.expected_time is not None else 8
## Если даты начала/окончания не указаны (Expected Start Date, Expected End Date), то дата начала = сегодня, дата окончания = завтра. 
## Если указана только дата начала, то дата окончания = дата начала + рабочие дни реализации, если указан только дата окончания, то дата начала = дата окончания - дни реализации.
## Если веха (чекбокс Is Milestone= true), то дата начала = дата завершения.
if doc.is_milestone:
        if not doc.exp_end_date:
            doc.exp_end_date = today
        doc.exp_start_date = doc.exp_end_date
        
if not doc.exp_start_date and not doc.exp_end_date:
    doc.exp_start_date = today
    doc.exp_end_date = frappe.utils.add_days(today, ceil(expected_time, 8))
else:
    if not doc.exp_start_date:
        doc.exp_start_date = frappe.utils.add_days(doc.exp_end_date, -1 * ceil(expected_time, 8))
    
    if not doc.exp_end_date:
        doc.exp_end_date = frappe.utils.add_days(doc.exp_start_date, ceil(expected_time, 8))
##Если статус = Completed, то проверка на флаг Confirm и автоматически сбрасывать на Pending Review, если текущий пользователь не автор или не Admin.
##Если статус = Completed и не указана дата завершения (Completed On), то дата завершения = сегодня.
if doc.status == 'Completed':
    if doc.confirm:
        if not frappe.session.user == doc.owner or not frappe.session.user in frappe.call("dinext_projects.dinext_projects.permissions.get_users_with_role", role="System Manager"):
            doc.status = 'Pending Review'
    
    if not doc.completed_on:            
        doc.completed_on = today

workflow_tasks = frappe.get_all('Workflow Task', filters={
   'wt_docname': doc.name
}, ignore_permissions=True)

for task in workflow_tasks:
   task_doc = frappe.get_doc('Workflow Task', task.name)
   task_doc.delete(ignore_permissions=True)

#Issue - ISS-2024-02909
"""
    При удалении DocShare для Issue или виртуальной задачи удаляем соответствующий DocShare.

    Если удаляется DocShare, где share_doctype == "Issue", то ищется виртуальная задача 
    (Task с custom_linked_issue = Issue) и удаляется DocShare с share_doctype = "Task" для того же пользователя.

    Если удаляется DocShare, где share_doctype == "Task" и задача является виртуальной,
    то удаляется соответствующий DocShare для Issue.
"""
if doc.share_doctype == "Issue":
    issue_name = doc.share_name  # Имя Issue, к которому привязан DocShare
    virtual_task = frappe.db.get_value("Task", {"custom_linked_issue": issue_name}, "name")
    if virtual_task:
        ds = frappe.db.get_value("DocShare", {
            "share_doctype": "Task",
            "share_name": virtual_task,
            "user": doc.user
        })
        if ds:
            frappe.delete_doc("DocShare", ds, ignore_permissions=True)
elif doc.share_doctype == "Task":
    linked_issue = frappe.db.get_value("Task", doc.share_name, "custom_linked_issue")
    if linked_issue:
        ds = frappe.db.get_value("DocShare", {
            "share_doctype": "Issue",
            "share_name": linked_issue,
            "user": doc.user
        })
        if ds:
            frappe.delete_doc("DocShare", ds, ignore_permissions=True)

#Issue - ISS-2024-02909

# Проверка: если задача является виртуальной, то поле issue должно быть пустым
if doc.get("type") == "Issue" and doc.get("issue"):
    frappe.throw(_("Виртуальная задача не может быть привязана к Issue"))

"""
Обработка создания дочерней задачи для Issue.
Если поле "issue" заполнено (задача привязана к Issue),
то обновляем поле "parent_task" текущей задачи, устанавливая виртуальную задачу,
связанную с этим Issue (по полю custom_linked_issue).
"""
# Если в задаче указана привязка к Issue
if doc.get("issue"):
    issue_name = doc.get("issue")
    # Находим виртуальную задачу для данного Issue
    virtual_task = frappe.db.get_value("Task", {"custom_linked_issue": issue_name}, "name")

    if virtual_task:
        # Обновляем поле parent_task текущей задачи для привязки к виртуальной задаче
        frappe.db.set_value("Task", doc.name, {
            "parent_task": virtual_task,
            })
        frappe.db.set_value("Task", virtual_task, {
            "is_group": True
            })
#Если у дочерней задачи поле parent_task указывает на виртуальную задачу (Task Type = Issue),
#то привязка к Issue делается на основании поля custom_linked_issue родительской виртуальной задачи.
elif doc.get("parent_task"):
    parent_task_doc = frappe.get_doc("Task", doc.get("parent_task"))
    if parent_task_doc.get("type") == "Issue" and parent_task_doc.get("custom_linked_issue"):
        # Если поле issue не заполнено, устанавливаем его из virtual_task
        if not doc.get("issue"):
            frappe.db.set_value("Task", doc.name, {
                "issue": parent_task_doc.get("custom_linked_issue")
            })

