# Тикет -- https://erp.dinord.ru/app/issue/ISS-2025-01841
if doc.reference_type == 'Workflow Task' and doc.allocated_to:
    task = frappe.get_cached_doc("Workflow Task", doc.reference_name)
    
    is_rejected = any(
        row.get("state") == "Отклонено" 
        for row in task.get("available_workflow_transitions", [])
    )
    needs_approval = any(
        row.get("action") == "Согласовано"
        for row in task.get("available_workflow_transitions", [])
    )
    
    if is_rejected:
        doc.run_trigger("workflow_rejection_notification")
    elif needs_approval:
        doc.run_trigger("workflow_approval_notification")

log("_________________ Workflow Task Processing Before Save _________________")
#log("Workflow Task Processing: " + frappe.utils.cstr( frappe.get("form_dict", args) ) )

#doc = frappe.get_doc( json.loads( frappe.get("form_dict", args ).get("doc") ) )
doc = frappe.get("form_dict", args ).get("doc")
log("Doc: " + frappe.utils.cstr( doc ) )

# Получаем необходимые данные о документе
reference_doctype = doc.doctype
log("Doctype: " + frappe.utils.cstr( reference_doctype ) )

workflow_name = frappe.db.get_value("Workflow", {"document_type": reference_doctype, "is_active": 1}, "name")

if ( workflow_name ):
    workflow = frappe.get_cached_doc("Workflow", workflow_name)
    log("Workflow: " + frappe.utils.cstr( workflow ) )
    log("Workflow State: " + frappe.utils.cstr( doc.get(workflow.workflow_state_field ) ) )
    
    old_doc = doc.get_doc_before_save()
    
    if ( old_doc ):
        # Получаем все открытые задачи для данного документа, не связанные с текущим состоянием воркфлоу
        log("Обработка выполненных Workflow Task.." )
        workflow_tasks = frappe.get_all('Workflow Task', filters={
            'wt_docname': doc.name,
            'doc': reference_doctype,
            'state': old_doc.get(workflow.workflow_state_field),
            'status': 'Working'
        }, ignore_permissions=True)
        
        shouldNotChangeState = False
        
        if workflow_tasks:
            tasks = [str(task.name) for task in workflow_tasks]
            log("Текущие WT: " + frappe.utils.cstr(tasks))
            
            wt_shares = frappe.get_all('DocShare', filters={
                'share_doctype': "Workflow Task",
                'share_name': ['in', tasks],
                'user': frappe.session.user
            }, fields=['share_name'], ignore_permissions=True)
            
            for task in workflow_tasks:
                workflow_task_doc = frappe.get_cached_doc('Workflow Task', task.name, ignore_permissions=True)
                transition = {}
                share = {}
                
                for x in workflow_task_doc.available_workflow_transitions: 
                    if x.next_state == doc.get(workflow.workflow_state_field):
                        transition = x
                        break
                for x in wt_shares: 
                    if x.share_name == task.name:
                        share = x
                        break
                
                if ( transition ):
                    if ( share ):
                        workflow_task_doc.status = 'Completed'
                        workflow_task_doc.next_state = doc.get(workflow.workflow_state_field)
                        workflow_task_doc.action = transition.action
                        workflow_task_doc.save(ignore_permissions=True)  # Сохраняем изменения
                
                        log( "Выполнена WT: " + frappe.utils.cstr(task.name))
                        doc.add_comment('Workflow', "Выполнена задача [" + transition.get('action', "-") + "]")
                        
                    elif ( transition.custom_all_users_with_role ):
                        log( "Пропущена WT: " + frappe.utils.cstr(task.name))
                        shouldNotChangeState = True
                else:
                    log( "Пропущена WT: " + frappe.utils.cstr(task.name))
        
        if ( shouldNotChangeState ):
            doc.set( workflow.workflow_state_field, old_doc.get(workflow.workflow_state_field ) )
            log( "Doc Workflow State: " + frappe.utils.cstr(doc.get(workflow.workflow_state_field)))
            frappe.flags.doc = doc
            frappe.response['message'] = doc

else:
    log("No active Workflow for DocType: " + frappe.utils.cstr( reference_doctype ) )

# 1. Получаем согласованные оценки
approved_estimations = []
for estimation in doc.estimations:
    if estimation.status == "Согласовано":
        approved_estimations.append(estimation)

if not approved_estimations:
    # Нет согласованных оценок - выходим
    pass
else:
    # 2. Получаем список праздников и коротких дней
    holiday_list = frappe.db.get_value("Project", doc.project, "holiday_list")
    holidays = []
    if holiday_list:
        holiday_records = frappe.db.get_all("Holiday", 
                                         filters={"parent": holiday_list},
                                         fields=["holiday_date"])
        for holiday in holiday_records:
            holidays.append(frappe.utils.getdate(holiday.holiday_date))
    
    # Получаем данные о коротких рабочих днях
    short_days = {}
    working_hours_on_date = frappe.db.get_value("Project", doc.project, "custom_working_hours_on_date")
    if working_hours_on_date:
        short_days_records = frappe.db.get_all("Working Hours Table", 
                                            filters={"parent": working_hours_on_date},
                                            fields=["wht_date", "wht_hours"])
        for record in short_days_records:
            short_days[frappe.utils.getdate(record.wht_date)] = frappe.utils.flt(record.wht_hours)

    # 3. Обрабатываем каждую оценку
    for estimation in approved_estimations:
        # Базовые данные
        project_role = estimation.project_role
        task = estimation.task
        if not task:
            task_record = frappe.db.get_value("Task", {"custom_linked_issue": doc.name}, "name")
            if task_record:
                task = task_record
        
        grade = frappe.utils.flt(estimation.grade)
        
        if not task and not project_role:
            frappe.throw("Не указана задача или роль проекта")

        # Даты периода
        start_date = frappe.utils.getdate(doc.opening_date)
        if doc.custom_expected_resolution_date:
            end_date = frappe.utils.getdate(doc.custom_expected_resolution_date)
        else:
            end_date = start_date

        # 4. Работа с Project Work Effort (с ignore_permissions)
        pwe_filters = {
            "pwe_project": doc.project,
            "pwe_task": task,
            "pwe_project_role": project_role
        }
        
        pwe_exists = frappe.db.exists("Project Work Efforts", pwe_filters)
        if pwe_exists:
            pwe = frappe.get_doc("Project Work Efforts", pwe_filters, ignore_permissions=True)
            # Получаем текущие данные
            current_data = []
            for row in pwe.pwe_amount:
                current_data.append({
                    "year": int(row.pwea_year),
                    "month": int(row.pwea_month),
                    "hours": frappe.utils.flt(row.pwea_plan, 2)
                })
        else:
            pwe = frappe.new_doc("Project Work Efforts")
            pwe.update(pwe_filters)
            current_data = []

        # 5. Рассчитываем новые данные только если нужно
        if not pwe_exists or current_data:
            # Расчет рабочих дней и часов
            months = []
            current_month = frappe.utils.get_first_day(start_date)
            last_month = frappe.utils.get_last_day(end_date)
            
            while current_month <= last_month:
                months.append({
                    "year": current_month.year,
                    "month": current_month.month,
                    "start": max(frappe.utils.get_first_day(current_month), start_date),
                    "end": min(frappe.utils.get_last_day(current_month), end_date)
                })
                # Переход к следующему месяцу
                if current_month.month == 12:
                    current_month = current_month.replace(year=current_month.year+1, month=1, day=1)
                else:
                    current_month = current_month.replace(month=current_month.month+1, day=1)

            # Считаем рабочие часы по месяцам
            working_hours_by_month = {}
            total_hours = 0
            
            for month in months:
                month_key = str(month['year']) + "-" + str(month['month'])
                working_hours_by_month[month_key] = 0
                
                current_day = month["start"]
                while current_day <= month["end"]:
                    if current_day.weekday() < 5:  # Пн-Пт
                        is_holiday = False
                        for h in holidays:
                            if h == current_day:
                                is_holiday = True
                                break
                        
                        if not is_holiday:
                            # Проверяем, является ли день коротким
                            day_hours = 8  # стандартный рабочий день
                            if current_day in short_days:
                                day_hours = short_days[current_day]
                            
                            # Обновляем значения
                            working_hours_by_month[month_key] = working_hours_by_month.get(month_key, 0) + day_hours
                            total_hours = total_hours + day_hours
                    
                    current_day = frappe.utils.add_days(current_day, 1)

            # Подготавливаем данные для сохранения
            new_data = []
            if total_hours > 0:
                for month_key in working_hours_by_month:
                    month_hours = working_hours_by_month[month_key]
                    if month_hours > 0:
                        year_month = month_key.split("-")
                        year = int(year_month[0])
                        month = int(year_month[1])
                        hours = frappe.utils.flt((grade * month_hours) / total_hours, 2)
                        new_data.append({
                            "year": year,
                            "month": month,
                            "hours": hours
                        })

            # 6. Сравниваем данные
            needs_update = not pwe_exists  # Новый документ всегда нужно сохранять
            
            if pwe_exists:
                if len(current_data) != len(new_data):
                    needs_update = True
                else:
                    for i in range(len(current_data)):
                        curr = current_data[i]
                        new = new_data[i]
                        if (curr["year"] != new["year"] or 
                            curr["month"] != new["month"] or 
                            abs(curr["hours"] - new["hours"]) > 0.0001):
                            needs_update = True
                            break

            # 7. Сохраняем только при изменениях (с ignore_permissions)
            if needs_update:
                if pwe_exists:
                    pwe.set("pwe_amount", [])
                
                for month in new_data:
                    pwe.append("pwe_amount", {
                        "pwea_year": month["year"],
                        "pwea_month": month["month"],
                        "pwea_plan": month["hours"],
                        "pwea_expected": month["hours"]
                    })
                
                pwe.save(ignore_permissions=True)

#Тикет - ISS-2025-01030
current_date = frappe.utils.nowdate()

# Проверяем таблицу cost_center_table и находим актуальный cost_center
worker_cost_center = None

if doc.cost_center_table:
    # Фильтруем записи по дате (valid_from <= текущая дата)
    valid_rows = []
    for row in doc.cost_center_table:
        if row.cct_valid_from and row.cct_valid_from <= current_date:
            valid_rows.append(row)
    
    # Находим запись с максимальной датой
    if valid_rows:
        closest_row = valid_rows[0]
        for row in valid_rows:
            if row.cct_valid_from > closest_row.cct_valid_from:
                closest_row = row
        worker_cost_center = closest_row.cct_cost_center

# Если нашли cost_center у Worker, продолжаем проверки
if worker_cost_center and doc.wuser:
    # Получаем Employee
    employee = frappe.db.get_value("Employee", {"user_id": doc.wuser}, 
                                 ["name", "payroll_cost_center", "department"], as_dict=1)
    
    if employee:
        # Проверяем cost center у Employee
        if employee.payroll_cost_center and employee.payroll_cost_center != worker_cost_center:
            frappe.msgprint(
                f"Внимание: Центр Затрат у Исполнителя ({worker_cost_center}) не совпадает с Центром затрат сотрудника ({employee.payroll_cost_center})",
                title="Несоответствие МВЗ",
                indicator="orange",
                alert=True
            )
        
        # Проверяем cost center у Department
        if employee.department:
            department = frappe.db.get_value("Department", employee.department, 
                                           "payroll_cost_center", as_dict=1)
            if department and department.payroll_cost_center and department.payroll_cost_center != worker_cost_center:
                frappe.msgprint(
                    f"Внимание: Центр Затрат у Исполнителя ({worker_cost_center}) не совпадает с Центром затрат отдела ({department.payroll_cost_center})",
                    title="Несоответствие МВЗ",
                    indicator="orange",
                    alert=True
                )

# Тикет -- https://erp.dinord.ru/app/issue/ISS-2025-01841
# Получаем предыдущую версию документа
old_doc = doc.get_doc_before_save()

# Проверяем наличие обязательных полей
if (
    doc.get("project") 
    and doc.get("table") 
    and (not old_doc or old_doc.status in (None, 'Редактирование'))
):

    # Получаем проект
    project = frappe.get_cached_doc("Project", doc.project)
    
    if project.get("custom_project_utilization"):
        # Обрабатываем каждую строку таблицы отдельно
        for row in doc.table:
            if not row.date:
                continue
                
            # Валидация даты без try-except
            row_date = frappe.utils.getdate(row.date)
            if not row_date:
                continue
                
            closest_record = None
            
            # Ищем подходящую запись об утилизации для даты строки
            for utilization in project.custom_project_utilization:
                if not utilization.pu_valid_from:
                    continue
                    
                pu_date = frappe.utils.getdate(utilization.pu_valid_from)
                if not pu_date:
                    continue
                    
                if pu_date <= row_date:
                    closest_pu_date = frappe.utils.getdate(closest_record.pu_valid_from) if closest_record else None
                    if not closest_record or (closest_pu_date and pu_date > closest_pu_date):
                        closest_record = utilization
            
            # Если нашли подходящую запись
            if closest_record:
                row_hours = frappe.utils.flt(row.hours)
                row_utilized = frappe.utils.flt(row.utilized_hours or 0)
                
                if closest_record.get("pu_included") == "Да":
                    # Если включено - обновляем utilized_hours если нужно
                    if row_hours > 0 and not (row_utilized == row_hours):
                        row.utilized_hours = row.hours
                        
                elif closest_record.get("pu_included") == "В рамках плана":
                    is_monthly = closest_record.get("pu_limit") == "В месяц"
                    log_prefix = "месяц" if is_monthly else "итого"
                    log(f"=== Начало обработки строки с датой {row.date} (режим '{log_prefix}') ===")
                    
                    # 1. Поиск плана (ТОЛЬКО ВВЕРХ по иерархии)
                    planned_task = None
                    planned_amounts = []
                    current_task = doc.document_name
                    
                    while current_task is not None and not planned_task:
                        # Проверяем текущую задачу
                        pwe_list = frappe.get_all("Project Work Efforts",
                            filters={
                                "pwe_project": doc.project,
                                "pwe_task": current_task,
                                "pwe_project_role": doc.project_role
                            },
                            fields=["name"],
                            limit=1
                        )
                        
                        if pwe_list and len(pwe_list) > 0:
                            pwe = frappe.get_cached_doc("Project Work Efforts", pwe_list[0]["name"])
                            for amount in pwe.pwe_amount:
                                if is_monthly:
                                    # Для месячного режима проверяем месяц и год
                                    db_month = int(amount.pwea_month) if amount.pwea_month else None
                                    db_year = int(amount.pwea_year) if amount.pwea_year else None
                                    if (db_year is not None and db_year == row_date.year and 
                                        db_month is not None and db_month == row_date.month and 
                                        frappe.utils.flt(amount.pwea_plan or 0) > 0):
                                        planned_task = current_task
                                        planned_amounts = [amount]
                                        break
                                else:
                                    # Для итогового режима собираем все планы
                                    if frappe.utils.flt(amount.pwea_plan or 0) > 0:
                                        planned_task = current_task
                                        planned_amounts.append(amount)
                        
                        # Переходим ТОЛЬКО к родителю
                        if not planned_task:
                            parent = frappe.db.get_value("Task", current_task, "parent_task")
                            current_task = parent if parent else None
                    
                    # 2. Получаем плановые часы
                    plan_hours = 0.0
                    if planned_task:
                        if is_monthly:
                            if planned_amounts:
                                plan_hours = frappe.utils.flt(planned_amounts[0].pwea_plan or 0)
                                log(f"Найден месячный план: {plan_hours} часов в задаче {planned_task}")
                        else:
                            plan_hours = sum([frappe.utils.flt(amount.pwea_plan or 0) for amount in planned_amounts])
                            log(f"Найден итоговый план: {plan_hours} часов (сумма {len(planned_amounts)} периодов) в задаче {planned_task}")
                    else:
                        log("План не найден ни в одной задаче, используем 0 часов")
            
                    # 3. Получаем ВСЕ дочерние задачи для сбора факта (любой уровень вложенности)
                    tasks_for_fact = []
                    if planned_task is not None:
                        # Начинаем с задачи, где найден план
                        tasks_to_process = [planned_task]
                        tasks_for_fact = []
                        while tasks_to_process:
                            current_task = tasks_to_process.pop()
                            tasks_for_fact.append(current_task)
                            # Получаем непосредственных детей
                            children = frappe.get_all("Task",
                                filters={"parent_task": current_task, "project": doc.project},
                                fields=["name"]
                            )
                            tasks_to_process.extend([child["name"] for child in children])
                        log(f"Используем {len(tasks_for_fact)} задач для сбора факта (планирующая + {len(tasks_for_fact)-1} дочерних любого уровня)")
                    else:
                        # Начинаем с текущей задачи
                        tasks_to_process = [doc.document_name]
                        tasks_for_fact = []
                        while tasks_to_process:
                            current_task = tasks_to_process.pop()
                            tasks_for_fact.append(current_task)
                            # Получаем непосредственных детей
                            children = frappe.get_all("Task",
                                filters={"parent_task": current_task, "project": doc.project},
                                fields=["name"]
                            )
                            tasks_to_process.extend([child["name"] for child in children])
                        log(f"План не найден, используем {len(tasks_for_fact)} задач для сбора факта (текущая + {len(tasks_for_fact)-1} дочерних любого уровня)")
            
                    # 4. Собираем фактические часы
                    actual_hours = 0.0
                    if len(tasks_for_fact) > 0:
                        utp_filters = {
                            "document_name": ["in", tasks_for_fact],
                            "project_role": doc.project_role,
                            "name": ["!=", doc.name]  # Исключаем текущий таймшит
                        }
                        
                        if is_monthly:
                            # Используем стандартные функции Frappe для определения диапазона месяца
                            first_day = frappe.utils.formatdate(f"{row_date.year}-{row_date.month:02d}-01", "yyyy-MM-dd")
                            last_day = frappe.utils.get_last_day(row_date)
                            
                            utp_filters["ut_valid_from"] = ["between", [first_day, last_day]]
                        
                        utp_list = frappe.db.get_all("User Timesheet Position", 
                            filters=utp_filters,
                            fields=["name"]
                        )
                        
                        for utp in utp_list:
                            utp_doc = frappe.get_cached_doc("User Timesheet Position", utp["name"])
                            for ts_row in utp_doc.table:
                                if ts_row.date:
                                    ts_date = frappe.utils.getdate(ts_row.date)
                                    if ts_date and (not is_monthly or (ts_date.month == row_date.month and ts_date.year == row_date.year)):
                                        actual_hours = actual_hours + frappe.utils.flt(ts_row.utilized_hours or 0)
                    
                    log(f"Общий факт: {actual_hours} часов")
            
                    # 5. Распределяем остаток
                    remaining_hours = frappe.utils.flt(plan_hours) - frappe.utils.flt(actual_hours)
                    log(f"Остаток часов: {remaining_hours}")
                    
                    if remaining_hours > 0:
                        # Собираем и сортируем строки по дате
                        valid_rows = []
                        for r in doc.table:
                            if r.date:
                                date_val = frappe.utils.getdate(r.date)
                                if date_val:
                                    valid_rows.append({
                                        "row": r,
                                        "date": date_val
                                    })
                        
                        # Сортируем по дате
                        valid_rows.sort(key=lambda x: x["date"])
                        
                        for item in valid_rows:
                            r = item["row"]
                            if remaining_hours <= 0:
                                r.utilized_hours = 0.0
                                continue
                            
                            hours = frappe.utils.flt(r.hours or 0)
                            if hours <= remaining_hours:
                                r.utilized_hours = hours
                                remaining_hours = remaining_hours - hours
                            else:
                                r.utilized_hours = remaining_hours
                                remaining_hours = 0.0
                    else:
                        for r in doc.table:
                            r.utilized_hours = 0.0
                    
                    log(f"=== Окончание обработки строки (режим '{log_prefix}') ===")
                
                else:
