def get_closest_business_area(table, log_date):
    closest_rows = []
    if table:
        closest_date = None
        for row in table:
            if row.valid_from:
                row_date = frappe.utils.getdate(row.valid_from)
                if row_date <= log_date:
                    if not closest_date or row_date > closest_date:
                        closest_date = row_date
                        closest_rows.clear()
                    if row_date == closest_date:
                        closest_rows.append( row )
    return closest_rows

