def apply_propagation(changes, mode="sync"):
    if mode not in ("sync", "async"):
        mode = "sync"
    if mode == "async":
        job = frappe.enqueue( function="apply_propagation", queue = "long", changes=changes )
        log( "job_id: " +  frappe.utils.cstr( job ) )
        return {"success": True, "job_id": frappe.utils.cstr( job.id ) }
    if isinstance(changes, str):
        changes = json.loads(changes)
    if not isinstance(changes, (list, tuple)):
        frappe.throw("changes must be a list")
    changed_count = 0
    applied = []
    for c in changes:
        t = c.get("task")
        if not t:
            continue
        doc = frappe.get_doc("Task", t)
        old_start = doc.get("exp_start_date", None)
        old_end = doc.get("exp_end_date", None)
        new_start = c.get("proposed_start") or old_start
        new_end = c.get("proposed_end") or old_end
        if new_start != old_start or new_end != old_end:
            if new_start is not None:
                doc.exp_start_date = new_start
            if new_end is not None:
                doc.exp_end_date = new_end
            doc.save(ignore_permissions=True)
            changed_count = changed_count + 1
            applied.append({"task": t, "old_start": old_start, "old_end": old_end, "new_start": new_start, "new_end": new_end})
    return {"success": True, "changed": changed_count, "applied": applied}


