    try:
        # attempt attribute access first
        val = getattr(doc, fieldname)
        return val
    except Exception:
        #try:
        if isinstance(doc, dict):
            #log( "isinstance(doc, dict): " +  frappe.utils.cstr( doc.get(fieldname) ) )
            return doc.get(fieldname)
        #except Exception:
        #    return None
    return None

# CHANGED: compute expected constraint values for a relation
def compute_expected_for_relation(predecessor_doc, successor_doc, rel_type, buffer_days, holidays):
    """
    Возвращает dict с ожидаемыми датами для successor:
    { "expected_start": date or None, "expected_end": date or None, "holiday_project": project_name }
    """
    # determine project / holidays based on successor project first, else predecessor
    proj = get_field_value(successor_doc, "project") or get_field_value(predecessor_doc, "project")
    p_start = predecessor_doc.exp_start_date 
    p_end = predecessor_doc.exp_end_date
    expected_start = None
    expected_end = None
    if rel_type == _("FS (Finish → Start)"):
        if p_end:
            expected_start = add_business_days(p_end, buffer_days, holidays)
    elif rel_type == _("SS (Start → Start)"):
        if p_start:
            expected_start = add_business_days(p_start, buffer_days, holidays)
    elif rel_type == _("FF (Finish → Finish)"):
        if p_end:
            expected_end = add_business_days(p_end, buffer_days, holidays)
    elif rel_type == _("SF (Start → Finish)"):
        if p_start:
            expected_end = add_business_days(p_start, buffer_days, holidays)
    return {"expected_start": expected_start, "expected_end": expected_end, "holidays": holidays, "project": proj}

def check_dependencies_for_tasks(project, tasks):
    """
    Input: tasks - list of task names OR JSON string of list.
    Output: { "results": [ { "checked_task": <task>, "violations": [ {...} ] }, ... ] }
    Violation structure: {
       "relation_role": "incoming" | "outgoing",
       "relation_type": "FS|SS|FF|SF",
       "predecessor": <task_name>,
       "successor": <task_name>,
       "violated_field": "start" | "end",
       "expected_date": "YYYY-MM-DD",
       "actual_date": "YYYY-MM-DD" or None,
       "buffer_days": int,
       "message": str
    }
    """
    # normalize input
    if isinstance(tasks, str):
        tasks = json.loads(tasks)
        #log( "tasks: " +  frappe.utils.cstr( tasks ) )
    if not isinstance(tasks, (list, tuple)):
        tasks = [tasks]
    
    task_names = [ task.get('name') for task in tasks ]
    log( "task_names: " +  frappe.utils.cstr( task_names ) )
    holidays = get_holiday_dates_for_project( project )
    results = []

    # For performance: load all relations where parent in tasks
    parent_rows = frappe.get_all("Task Relation",
                                filters=[["parent", "in", task_names], ["is_active", "=", 1]],
                                fields=["parent", "predecessor", "type", "buffer_days"])
    #log( "parent_rows: " +  frappe.utils.cstr( parent_rows ) )

    # Build fast map: for each task, incoming relations
    incoming_map = {}
    for r in parent_rows:
        parent = r["parent"]
        pred = r["predecessor"]
        typ = r["type"]
        buf = r["buffer_days"]
        incoming_map.setdefault(parent, []).append({"predecessor": pred, "type": typ, "buffer": buf})
    #log( "incoming_map: " +  frappe.utils.cstr( incoming_map ) )

    # For each input task produce violations list
    for task in tasks:
        task_result = {"checked_task": task.get('name'), "violations": [] }
        # 1) Check incoming constraints for task t (task is successor)
        succ_doc = task
        #log( "succ_doc: " +  frappe.utils.cstr( succ_doc ) )
        incs = incoming_map.get(task.get('name'), [])
        for rel in incs:
            predecessor_name = rel["predecessor"]
            rel_type = rel["type"]
            buffer_days = int(rel["buffer"] or 0)
            pred_doc = None
            for t in tasks:
                if t.name == predecessor_name:
                    pred_doc = t
                    break
            pred_doc = pred_doc or ( frappe.get_doc("Task", predecessor_name) if predecessor_name else None )
            # compute expected for successor
            computed = compute_expected_for_relation(pred_doc, succ_doc, rel_type, buffer_days, holidays)
            expected_start = computed.get("expected_start")
            expected_end = computed.get("expected_end")
            # get actual successor dates
            actual_start = parse_date(get_field_value(succ_doc, "exp_start_date"))
            actual_end = parse_date(get_field_value(succ_doc, "exp_end_date"))
            # compare and add violations
            if expected_start:
                # expected_start <= actual_start
                if (not actual_start) or (actual_start < expected_start):
                    task_result["violations"].append({
                        "relation_type": rel_type,
                        "predecessor": predecessor_name,
                        "violated_field": "start",
                        "expected_date": format_date(expected_start),
                        "actual_date": format_date(actual_start),
                        "buffer_days": buffer_days,
                        "message": _("Successor start must be >= %s") % format_date(expected_start)
                    })
            if expected_end:
                # expected_end <= actual_end
                if (not actual_end) or (actual_end < expected_end):
                    task_result["violations"].append({
                        "relation_type": rel_type,
                        "predecessor": predecessor_name,
                        "violated_field": "end",
                        "expected_date": format_date(expected_end),
                        "actual_date": format_date(actual_end),
                        "buffer_days": buffer_days,
                        "message": _("Successor end must be >= %s") % format_date(expected_end)
                    })
            log( "task_result: " +  frappe.utils.cstr( task_result ) )
                    
        results.append(task_result)

    return results


log("_________________ check_dependencies_for_tasks _________________")

